window.RP_SESSION={"id":"S-e4b93f3bdf48","messages":[{"id":"RP-0190318","time":"2026-07-10T12:36:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 아 안둘거야? 오목 두자며 --^ \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190319","time":"2026-07-10T12:37:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"어설픈 용맹, 거실.\n\n숀이 테이블 위 오목판을 톡톡톡톡톡... 손가락으로 두드리며 당신을 재촉합니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-0190320","time":"2026-07-10T12:38:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"어, 근데 왜 가운데가 아니라 살짝 왼쪽에서 시작하는건가요...?\"","characters":["P-79263e0865dd"]},{"id":"RP-0190321","time":"2026-07-10T12:38:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 야 내 맘이쥐. 33 안된다. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190322","time":"2026-07-10T12:39:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"아, 옙\"","characters":["P-79263e0865dd"]},{"id":"RP-0190323","time":"2026-07-10T12:40:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190324","time":"2026-07-10T12:41:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190325","time":"2026-07-10T12:41:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 요새 연구는 좀 어때? 뭐 이거저거 바빠 보이든데. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190326","time":"2026-07-10T12:43:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190327","time":"2026-07-10T12:43:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"아, 좀 바쁘긴 하죠... 연구도 진척이 없고, 최근엔 장례식이라던가 여러모로 일이 많았어서...\"","characters":["P-79263e0865dd"]},{"id":"RP-0190328","time":"2026-07-10T12:44:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190329","time":"2026-07-10T12:44:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그래? 근데 그거 돈은 되는거야? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190330","time":"2026-07-10T12:45:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190331","time":"2026-07-10T12:45:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"글쎄요... 애초에 돈을 보고 하는 연구는 아니니까요\"","characters":["P-79263e0865dd"]},{"id":"RP-0190332","time":"2026-07-10T12:45:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"음... 그나마 논문으로 인정은 받겠죠?\"","characters":["P-79263e0865dd"]},{"id":"RP-0190333","time":"2026-07-10T12:46:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190334","time":"2026-07-10T12:46:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 흠, 그래? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190335","time":"2026-07-10T12:49:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190336","time":"2026-07-10T12:49:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그리고 돈이 된다고 하더라도 시간이 워낙 오래걸릴 거에요. 에피메네우스 선배님이랑 헤일리씨가 도와주신다고 했었는데... 선배님은 바빠보이시고, 헤일리씨는 결혼으로 떠나셨더라고요. 혼자서는 한계가 있으니, 아주 오래동안 달려갈 장기프로젝트가 되겠죠.\"","characters":["P-79263e0865dd"]},{"id":"RP-0190337","time":"2026-07-10T12:49:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190338","time":"2026-07-10T12:50:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그렇드라. 갔어? 결혼식. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190339","time":"2026-07-10T12:51:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190340","time":"2026-07-10T12:51:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"아뇨... 연구가 바쁘기도 했고, 또 헤일리씨가 떠난다니 급하게 구해야할 자료들이 많아진 탓에... 헤일리씨에겐 좀 죄송하죠\"","characters":["P-79263e0865dd"]},{"id":"RP-0190341","time":"2026-07-10T12:52:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190342","time":"2026-07-10T12:52:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그 녀석. 혼삿일이 하루만에 뚝딱 되는 것도 아니고, 결혼 준비하면서 연구도 돕겠다고 자처했다니.\n\n\n... 좋은 녀석이었쥐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190343","time":"2026-07-10T12:54:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190344","time":"2026-07-10T12:54:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그쵸, 좋은 분이셨어요. 호기심도 많으셨고, 배움에 대한 욕심도 크셨죠. 인사라도 하고 떠났으면 좋았을텐데...\"","characters":["P-79263e0865dd"]},{"id":"RP-0190345","time":"2026-07-10T12:59:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190346","time":"2026-07-10T12:59:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그러게. 뭐, 영영 못보는 건 아니니까. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190347","time":"2026-07-10T13:00:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190348","time":"2026-07-10T13:00:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그렇죠. 그래도 사지 멀쩡하게 떠난게 다행인가 싶기도 하고\"","characters":["P-79263e0865dd"]},{"id":"RP-0190349","time":"2026-07-10T13:02:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190350","time":"2026-07-10T13:02:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 나중에 한 번 밥이나 먹으러오라고 편지해보쥐 뭐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190351","time":"2026-07-10T13:04:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190352","time":"2026-07-10T13:04:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"좋네요~ 한번 오시면 그동안의 연구 진척도 좀 보여드려야겠어요. 공동저자로 이름을 올려드리기로 했거든요.\"","characters":["P-79263e0865dd"]},{"id":"RP-0190353","time":"2026-07-10T13:06:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190354","time":"2026-07-10T13:06:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 근데 넌 언제가냐? ㅋㅋㅋㅋ \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190355","time":"2026-07-10T13:08:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190356","time":"2026-07-10T13:08:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"뭣. 숀씨... 혹시 저도 떠났으면 좋겠다는 거에요...? 거지가 길드 정문에 걸터앉아있으면 사람들 발길 끊길까봐...?\"","characters":["P-79263e0865dd"]},{"id":"RP-0190357","time":"2026-07-10T13:09:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190358","time":"2026-07-10T13:10:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 아니 결혼말야 결혼 -- \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190359","time":"2026-07-10T13:12:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-79263e0865dd"]},{"id":"RP-0190360","time":"2026-07-10T13:12:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"앗차차... 그럼 처음부터 그렇게 말해주시지. 음... 근데 저랑 결혼은 고사하고, 만나줄 여성분이 계실지 모르겠네요.\"","characters":["P-79263e0865dd"]},{"id":"RP-0190361","time":"2026-07-10T13:14:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" ㅎ. 그래? \"\n\n....탁!","characters":["P-5c88d36f51cd"]},{"id":"RP-0190362","time":"2026-07-10T13:14:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-5c88d36f51cd"]},{"id":"RP-0190363","time":"2026-07-10T13:15:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"앗, 졌네요. 그보다 아까부터 제 이야기만 한거 같은데, 숀씨 이야기도 좀 해줘요. 요즘 별일 없었어요? 음, 마리아 일 말고...\"","characters":["P-79263e0865dd"]},{"id":"RP-0190364","time":"2026-07-10T13:17:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"드르륵... 드륵...\n\n숀은 오목돌을 정리하며 얘기했습니다.\n\n\" 그냥쥐냥 살쥐. 뭐 요샌 만나는 여자도 없고. 일감도 줄고... 아 맞다, 브랜이라고 알쥐? 새로 온 친구. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190365","time":"2026-07-10T13:19:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"정리를 도와줍니다. 백돌 흑돌을 나눠주고 있네요.\n\n\"아, 그 대장간에 계신 분이요? 말씀 나눠본 적은 없는데, 오다가다 몇번 뵌 거 같아요\"","characters":["P-79263e0865dd"]},{"id":"RP-0190366","time":"2026-07-10T13:20:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"뭣. 청돌이 아니었다고.\n\n\" 응. 나도 몇 마디 나눠봤는데 재능이 많더라구. 대장장이 일을 배워봤다길래 내가 추천서를 넣어준댔어. 우리 길드는 지금 대장장이... 가 공석이니까.\n\n계속 도시 대장간에 일 맡기는 것도 그렇고.\n\n비싸고. 귀찮아.\n\n무튼...\n\n좋은 녀석 같더라구. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190367","time":"2026-07-10T13:22:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"백색으로 하니까 잘 안보여서 ㅎㅎ\n\n\"그렇군요. 잘 됐네요~ 안 그래도 대장간이 계속 비어있던게 신경쓰였거든요.\"\n\n요새 마리우스가 여러모로 다사다난했지~","characters":["P-79263e0865dd"]},{"id":"RP-0190368","time":"2026-07-10T13:25:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 헬리가 나간 뒤로 마리우스 혼자 애썼으니까. 그 녀석한테도 차라리 잘된 거야.\n\n괜히 욕 먹는 것 보다야... \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190369","time":"2026-07-10T13:26:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"저번에 한번 뵀는데, 많이 힘들어보이시더라구요. 그래도 션씨가 잘 챙겨주시겠죠...?\"","characters":["P-79263e0865dd"]},{"id":"RP-0190370","time":"2026-07-10T13:35:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그렇겠쥐...? \"\n\n드르륵.\n... 타각.\n\n숀은 오목판을 정리하고 창 밖을 바라봤습니다.\n\n\" 어. 비온다. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190371","time":"2026-07-10T13:38:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"아, 이런\"\n\n이따 외출 좀 하려했는데 말이죠. 오늘은 그냥 책이나 더 읽어야겠습니다. 비가 오니 뜨끈한 국물이 땡기는군요.\n\n\"전 이제 밥먹으러 가보려고요. 숀씨는요?\"","characters":["P-79263e0865dd"]},{"id":"RP-0190372","time":"2026-07-10T13:58:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 응? 어. \n\n가야쥐. 밥 먹으러.\n\n넌 어디서 먹게? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190373","time":"2026-07-10T13:58:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"카프리제씨한테 부탁드리려고요. 비가 오니 따뜻한게 땡기네요\"","characters":["P-79263e0865dd"]},{"id":"RP-0190374","time":"2026-07-10T14:22:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 오! 마침 잘됐네, 어차피 지금 딱 밥 때니까 기왕이면 머독이나 마리ㅇ... \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190375","time":"2026-07-10T14:22:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" ...우스도, 먹자고 하면. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0190376","time":"2026-07-10T14:23:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"...좋네요\"","characters":["P-79263e0865dd"]},{"id":"RP-0190377","time":"2026-07-10T14:23:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"그냥... 눈에 보이는 아무나 붙잡고 같이 밥먹자고 끌고가버리죠!\"","characters":["P-79263e0865dd"]},{"id":"RP-0190378","time":"2026-07-10T15:36:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그렇게 그들은 대충 근처에 보이던 델타인을 붙잡고 밥을 먹기로 합니다","characters":["P-79263e0865dd"]},{"id":"RP-0190379","time":"2026-07-10T15:37:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"스튜는 따뜻했습니다","characters":["P-79263e0865dd"]},{"id":"RP-0190380","time":"2026-07-10T15:37:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-79263e0865dd"]},{"id":"RP-0190381","time":"2026-07-10T15:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
